INSERT INTO itinerary (entry_id,trip_id,place_id,item_type,title,start_date,end_date,start_time,end_time,departure_timezone,arrival_timezone,from_location,to_location,confirmation_code,notes) VALUES (17,'sample-coast',11,'place',NULL,'2026-05-18',NULL,'11:15','12:30',NULL,NULL,NULL,NULL,NULL,'Long-note test: the overlook trail is short and flat, but the view of the waterfall dropping straight onto the beach is worth the crowds. Go early, before the tour buses, and walk past the first viewpoint to the stone terrace at the end, where the old house used to stand. Bring a layer; the wind off the water is colder than it looks.');
