INSERT INTO itinerary (entry_id,trip_id,place_id,item_type,title,start_date,end_date,start_time,end_time,departure_timezone,arrival_timezone,from_location,to_location,confirmation_code,notes) VALUES (21,'sample-coast',19,'lodging',NULL,'2026-05-18','2026-05-19','16:00','10:00',NULL,NULL,NULL,NULL,NULL,'Cabins under the redwoods, next to the river.');
INSERT INTO itinerary (entry_id,trip_id,place_id,item_type,title,start_date,end_date,start_time,end_time,departure_timezone,arrival_timezone,from_location,to_location,confirmation_code,notes) VALUES (22,'sample-coast',NULL,'note','Fog over the ridge','2026-05-18',NULL,'18:00',NULL,NULL,NULL,NULL,NULL,NULL,'Long-note test: the fog came up the canyon in about ten minutes and swallowed the whole ridge. We sat on the porch and watched the redwoods disappear one by one, then reappear as it thinned out. Somebody in the next cabin was playing guitar. Nobody talked much, and nobody minded.');
INSERT INTO itinerary (entry_id,trip_id,place_id,item_type,title,start_date,end_date,start_time,end_time,departure_timezone,arrival_timezone,from_location,to_location,confirmation_code,notes) VALUES (23,'sample-coast',NULL,'transit','Shuttle to Pfeiffer Beach','2026-05-19',NULL,'10:30','10:50','America/Los_Angeles','America/Los_Angeles','Big Sur River Lodge','Pfeiffer Beach',NULL,NULL);
INSERT INTO itinerary (entry_id,trip_id,place_id,item_type,title,start_date,end_date,start_time,end_time,departure_timezone,arrival_timezone,from_location,to_location,confirmation_code,notes) VALUES (24,'sample-coast',13,'place',NULL,'2026-05-19',NULL,'11:00','12:15',NULL,NULL,NULL,NULL,NULL,'בדיקת טקסט ארוך: החול כאן סגול בגלל המינרלים מהצוקים, ובשעות הבוקר המוקדמות אפשר לראות את האור עובר דרך הקשת בסלע. החניה קטנה מאוד ומתמלאת מהר, אז כדאי להגיע לפני עשר ולהביא נעליים שלא אכפת לכם שיירטבו.');
INSERT INTO itinerary (entry_id,trip_id,place_id,item_type,title,start_date,end_date,start_time,end_time,departure_timezone,arrival_timezone,from_location,to_location,confirmation_code,notes) VALUES (25,'sample-coast',14,'place',NULL,'2026-05-19',NULL,'14:00','15:00',NULL,NULL,NULL,NULL,NULL,'No-coordinates test: this place has no location, so no map pin.');
INSERT INTO itinerary (entry_id,trip_id,place_id,item_type,title,start_date,end_date,start_time,end_time,departure_timezone,arrival_timezone,from_location,to_location,confirmation_code,notes) VALUES (26,'sample-coast',NULL,'note','ערב אחרון על החוף','2026-05-19',NULL,'15:20',NULL,NULL,NULL,NULL,NULL,NULL,'בדיקת פתק ארוך: ישבנו על הסלעים עד שהשמש נגעה במים, ואז עוד קצת. מישהו הביא תרמוס עם תה, ומישהו אחר מצא כלב ים שישן על החוף ממש מתחתינו. כשהתחיל להיות קר חזרנו לאט לרכב, בלי למהר, כי לא היה לאן.');
INSERT INTO itinerary (entry_id,trip_id,place_id,item_type,title,start_date,end_date,start_time,end_time,departure_timezone,arrival_timezone,from_location,to_location,confirmation_code,notes) VALUES (27,'sample-coast',20,'lodging',NULL,'2026-05-19','2026-05-21','17:30','08:00',NULL,NULL,NULL,NULL,NULL,'Changeover test: checks in the day the river lodge checks out, and checks out the day after the trip ends.');
